import os,json,subprocess,stat,time
from pathlib import Path
aliases={"/etc/pink-vpn":"/srv/projects/pink-iptv/vpn/gateway","/var/lib/pink-vpn":"/srv/projects/pink-iptv/vpn/data"}
out={"project":"pink-iptv","status":"BLOCKED","changed":False}
removed=[]
def run(args,t=10):return subprocess.run(args,capture_output=True,text=True,timeout=t)
def state():return {n:run(["systemctl","is-active",n]).stdout.strip() for n in ("ssh","nginx","pink-vpn","pink-iptv-backend","lowcost-europa","fadego-staging","pm2-root","pm2-iptvpn-bot")}
def vpn():
 r=run(["systemctl","show","pink-vpn","-p","MainPID,NRestarts,ActiveState,SubState"],8)
 return dict(line.split("=",1) for line in r.stdout.splitlines() if "=" in line)
def socket_listening():
 p=Path("/run/pink-vpn/control.sock")
 try:
  if not stat.S_ISSOCK(p.stat().st_mode):return False
  q=run(["ss","-H","-lxnp"],9)
  return q.returncode==0 and "/run/pink-vpn/control.sock" in q.stdout
 except OSError:return False
try:
 for old,target in aliases.items():
  p=Path(old);t=Path(target)
