 out.update(status="ALIASES_REMOVED_VERIFIED",changed=True,removed_aliases=removed,code_and_state_preserved=True,service_pid_unchanged=True,restart_count_unchanged=True,socket_passively_listening=True,services_unchanged=True)
except Exception as e:
 out["reason"]=str(e)[:150]
 if removed:
